#### From mathcomp Require Import all_algebra all_ssreflect. From mathcomp Require Import reals geometry. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Local Open Scope ring_scope. Variable R : realType. Theorem putnam_geometry_pyramid_volume : let A := (0, 0) : R * R in let B := (12 * sqrt 3, 0) in let C := (12 * sqrt 3, 13 * sqrt 3) in let D := (0, 13 * sqrt 3) in let line_AC := fun t : R => (A.1 + t * (C.1 - A.1), A.2 + t * (C.2 - A.2)) in let line_BD := fun s : R => (B.1 + s * (D.1 - B.1), B.2 + s * (D.2 - B.2)) in let P := (72, 78) in area A B P + area B C P + area C D P + area D A P = 1872.
